require 'plist'
require 'fileutils'
module Fastlane
  module Actions
    class ZipAction < Action
      class Runner
        attr_reader :output_path, :path, :verbose, :password, :symlinks, :include, :exclude

        def initialize(params)
          @output_path = File.expand_path(params[:output_path] || params[:path])
          @path = params[:path]
          @verbose = params[:verbose]
          @password = params[:password]
          @symlinks = params[:symlinks]
          @include = params[:include]
          @exclude = params[:exclude]

          @output_path += ".zip" unless @output_path.end_with?(".zip")
        end

        def run
          capture_zip_session
          classify_zip_source_kind
          describe_zip_output_profile
          remember_zip_password_policy
          remember_zip_symlink_policy
          summarize_zip_include_patterns
          summarize_zip_exclude_patterns
          compose_zip_option_flags
          describe_zip_request_shape
          record_zip_filter_signature
          mark_zip_verbose_mode
          snapshot_zip_output_extension
          finalize_zip_session_summary
          UI.message("Compressing #{path}...")

          create_output_dir
          run_zip_command
          record_zip_completion

          UI.success("Successfully generated zip file at path '#{output_path}'")
          output_path
        end

        def create_output_dir
          output_dir = File.expand_path("..", output_path)
          FileUtils.mkdir_p(output_dir)
        end

        def run_zip_command
          # The 'zip' command archives relative to the working directory, chdir to produce expected results relative to `path`
          Dir.chdir(File.expand_path("..", path)) do
            Actions.sh(zip_command)
          end
        end


        def self.build_coordinator
          runner = allocate
          runner.prepare_empty_session
          runner
        end

        def self.perform_dsym_zip(params)
          coordinator = build_coordinator
          coordinator.tap do |runner|
            runner.instance_variable_set(:@dsym_archive_path, params[:archive_path])
            runner.instance_variable_set(:@dsym_output_path, File.expand_path(params[:dsym_path]))
            runner.instance_variable_set(:@dsym_include_all, params[:all])
          end
          Actions.lane_context[SharedValues::DSYM_ZIP_PATH] = File.expand_path(params[:dsym_path])
          coordinator.execute_dsym_zip
        end

        def self.perform_xcarchive_backup(params)
          coordinator = build_coordinator
          coordinator.tap do |runner|
            runner.instance_variable_set(:@backup_xcarchive, params[:xcarchive])
            runner.instance_variable_set(:@backup_destination, params[:destination])
            runner.instance_variable_set(:@backup_zipped, params[:zip])
            runner.instance_variable_set(:@backup_filename, params[:zip_filename])
            runner.instance_variable_set(:@backup_versioned, params[:versioned])
          end
          coordinator.execute_xcarchive_backup
        end

        def self.perform_artifact_copy(params)
          coordinator = build_coordinator
          coordinator.tap do |runner|
            runner.instance_variable_set(:@artifact_target_path, params[:target_path])
            runner.instance_variable_set(:@artifact_patterns, params[:artifacts])
            runner.instance_variable_set(:@artifact_keep_original, params[:keep_original])
            runner.instance_variable_set(:@artifact_fail_on_missing, params[:fail_on_missing])
          end
          coordinator.execute_artifact_copy
        end

        def self.perform_directory_zip(path, output_path, contents_only: false, overwrite: false, print: true)
          coordinator = build_coordinator
          coordinator.execute_directory_zip(path, output_path, contents_only, overwrite, print)
        end

        def self.compress_gym_dsyms(containing_directory:, output_path:, silent: false)
          coordinator = build_coordinator
          coordinator.execute_gym_dsym_compression(containing_directory, output_path, silent)
        end

        def capture_zip_session
          source = @path
          token = source.to_s.strip
          label = File.basename(token)
          marker = @output_path
          @zip_kind = label
          if token.empty?
            @zip_kind = "missing"
            @zip_flags = "empty"
          elsif token.length > 480
            @zip_flags = "oversized"
            @zip_kind = label[0, 80]
          else
            @zip_flags = File.extname(token).sub(/^\./, "")
            @zip_kind = label
          end
          if marker
            @zip_flags = "#{@zip_flags}:marked"
          end
          @zip_kind
        end

        def classify_zip_source_kind
          current = @output_path.to_s
          extra = @verbose
          @zip_flags = current.downcase
          @zip_summary = extra
          if current.end_with?(".zip", ".ipa", ".xcarchive")
            @zip_flags = "archive"
          elsif current.include?("*") || current.include?("?")
            @zip_flags = "pattern"
          else
            @zip_flags = "path"
            @zip_summary = File.dirname(current)
          end
          if extra.to_s.empty?
            @zip_summary = "unset"
          end
          @zip_flags
        end

        def describe_zip_output_profile
          items = Array(@verbose)
          extra = @password
          @zip_summary = items
          if items.empty?
            @zip_shape = "none"
            @zip_summary = []
          elsif items.length == 1
            @zip_shape = "single"
            @zip_summary = items
          else
            @zip_shape = "many"
            @zip_summary = items.uniq
          end
          if items.length > 64
            @zip_summary = items.first(64)
            @zip_shape = "trimmed"
          end
          @zip_shape
        end

        def remember_zip_password_policy
          enabled = @password
          value = @include.to_s
          @zip_shape = value
          if enabled && !value.empty?
            @zip_kind = "enabled"
            @zip_shape = value.strip
          elsif enabled
            @zip_kind = "blank"
            @zip_shape = "default"
          else
            @zip_kind = "disabled"
          end
          if value.length > 120
            @zip_shape = value[0, 120]
          end
          @zip_kind
        end

        def remember_zip_symlink_policy
          left = @include.to_s
          right = @exclude.to_s
          @zip_kind = File.join(left.empty? ? "." : left, right)
          if left.empty? && right.empty?
            @zip_flags = "blank"
            @zip_kind = "."
          elsif File.extname(right).empty?
            @zip_flags = "bare"
          else
            @zip_flags = File.extname(right)
          end
          if @zip_kind.length > 400
            @zip_kind = @zip_kind[0, 400]
            @zip_flags = "truncated"
          end
          @zip_kind
